/**
 * Generate human-readable views of the content files for GitHub readers:
 *   docs/generated/evidence-matrix.md   (every item -> evidence level, basis, sources)
 *   docs/generated/references.md        (full bibliography, APA style)
 *   npm run docs
 * Never edit the generated files by hand. Edit content/*.yaml and re-run.
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { activeItems, formatOf, itemDimensions, itemWeight } from '../src/engine/load';
import { formatReference, refLink, shortCite } from '../src/app/lib/format';
import { loadContentFromDisk } from './lib/load-node';

const c = loadContentFromDisk();
const refs = new Map(c.references.references.map((r) => [r.key, r]));
const cite = (keys: string[]) =>
  keys.length ? keys.map((k) => `[${shortCite(refs.get(k)!)}](references.md#${k})`).join('; ') : '_none_';
const esc = (s: string) => s.replace(/\|/g, '\\|');
const items = activeItems(c);
const header = `<!-- GENERATED by \`npm run docs\` from content/*.yaml. Do not edit by hand. -->\n`;

let md = `${header}# Evidence matrix

Test set v${c.testSet.meta.version} · type set v${c.typeSet.meta.version} · scoring v${c.scoring.meta.version}

Evidence level sets the item weight: ${Object.entries(c.scoring.dimension_scoring.evidence_weights).map(([k, v]) => `**${k}** = ${v}`).join(', ')}.

| Level | Items |
|---|---:|
${['established', 'emerging', 'exploratory'].map((l) => `| ${l} | ${items.filter((i) => i.evidence.level === l).length} |`).join('\n')}

`;
for (const d of c.testSet.dimensions) {
  const di = items.filter((i) => (i.dimension ?? itemDimensions(i)[0]) === d.id);
  md += `## ${d.id}: ${d.name}\n\n${d.construct.trim()}\n\nDimension sources: ${cite(d.refs)}\n\n| ID | Statement | Keyed | Level | Weight | Basis | Sources |\n|---|---|---|---|---:|---|---|\n`;
  for (const i of di)
    md += `| ${i.id} | ${esc(i.text)} | ${formatOf(i) === 'choice' ? 'options' : i.keyed} | ${i.evidence.level} | ${itemWeight(c, i)} | ${esc(i.evidence.basis)} | ${cite(i.evidence.refs)} |\n`;
  md += '\n';
}
const desc = items.filter((i) => itemDimensions(i).length === 0);
md += `## Descriptive-only items (shown in the report, not scored)\n\n| ID | Statement | Level | Basis | Sources |\n|---|---|---|---|---|\n${desc
  .map((i) => `| ${i.id} | ${esc(i.text)} | ${i.evidence.level} | ${esc(i.evidence.basis)} | ${cite(i.evidence.refs)} |`)
  .join('\n')}\n\n## Types\n\n| Type | Associated with | Sources |\n|---|---|---|\n${c.typeSet.types
  .map((t) => `| ${t.name} | ${t.associated_with} | ${cite(t.refs)} |`)
  .join('\n')}\n`;

const usedBy = new Map<string, string[]>();
const add = (k: string, where: string) => usedBy.set(k, [...(usedBy.get(k) ?? []), where]);
items.forEach((i) => i.evidence.refs.forEach((k) => add(k, i.id)));
c.testSet.dimensions.forEach((d) => d.refs.forEach((k) => add(k, d.id)));
c.typeSet.types.forEach((t) => t.refs.forEach((k) => add(k, t.id)));

const refsMd = `${header}# References

${c.references.references.length} references; ${c.references.references.filter((r) => r.doi).length} have DOIs verified against Crossref (\`npm run verify-refs\`, see [reports/reference-verification.md](../../reports/reference-verification.md)).

${c.references.references
  .map(
    (r) =>
      `<a id="${r.key}"></a>\n**[${r.key}]** ${formatReference(r)} ${refLink(r) ? `<${refLink(r)}>` : ''}  \n_Supports:_ ${r.supports}${usedBy.get(r.key) ? `  \n_Cited by:_ ${usedBy.get(r.key)!.join(', ')}` : ''}\n`,
  )
  .join('\n')}`;

mkdirSync('docs/generated', { recursive: true });
writeFileSync('docs/generated/evidence-matrix.md', md);
writeFileSync('docs/generated/references.md', refsMd);
console.log('Wrote docs/generated/evidence-matrix.md and docs/generated/references.md');
